<script setup>
import { inject, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { commentApi, commentDate, commentRoot, openSecureSessionComment, secureCommentState, sessionCommentsQuery } from './sessionComments';
const props = defineProps({ clientId: [Number, String], family: Boolean, schedulePath: String, scheduleQuery: { type: Object, default: () => ({}) } });
const api = inject('secureSessionCommentsApi', commentApi), router = useRouter(), route = useRoute();
const records = ref([]), loading = ref(false), hasMore = ref(false), nextBefore = ref(null), error = ref(''); let generation = 0;
async function load(older = false) { const own = ++generation; if (!older) records.value = []; error.value = ''; loading.value = true;
  try { const { data } = await api.get(`${commentRoot}/history`, { params: { clientId: props.clientId || undefined, before: older ? nextBefore.value : undefined }, skipGlobalLoading: true }); if (own === generation) { records.value = older ? [...records.value, ...(data.comments || [])] : (data.comments || []); hasMore.value = data.hasMore; nextBefore.value = data.nextBefore; } }
  catch(e) { if (own === generation) error.value = e.response?.data?.error?.message || 'Secure session comment history could not be loaded.'; }
  finally { if (own === generation) loading.value = false; }
}
function appointment(record) { return record.appointment || record; }
function link(record) { const a = appointment(record), id = a.id || a.appointmentId; const prefix = route?.params?.organizationSlug ? `/${route.params.organizationSlug}` : ''; return { path: props.schedulePath || (props.family ? route.path : route?.meta?.auricwellPreview ? `${prefix}/appointments` : `${prefix}/my-schedule`), query: { ...props.scheduleQuery, ...sessionCommentsQuery(id, a.clientId || props.clientId), ...(props.family ? { panel: 'appointments', childId: String(a.clientId || props.clientId), appointmentId: String(id) } : { scheduleAction: 'appointment', scheduleAppointmentId: String(id) }) } }; }
function open(record) { const a = appointment(record); router?.push(link(record)).catch(() => {}); openSecureSessionComment(a.id || a.appointmentId, a.clientId || props.clientId); }
function href(record) { return router?.resolve(link(record)).href || '#'; }
watch(() => [props.clientId, secureCommentState.revision], () => load(false), { immediate: true });
</script>
<template><section class="aw-secure-history" aria-label="Secure session comment communication history"><h3>Secure session comments</h3><p>Comments stay attached to their session, including past appointments. Only comments shared with your current account are listed.</p><p v-if="loading" role="status">Loading secure comments…</p><p v-if="error" role="alert">{{ error }}</p><button v-if="error" type="button" @click="load(false)">Try again</button><p v-if="!loading && !error && !records.length">No secure session comments are available to your account.</p><ol><li v-for="record in records" :key="record.id"><strong>🔒 Secure comment</strong><span> · {{ record.author?.name || 'Care team' }} · {{ commentDate(record.createdAt, appointment(record).timeZone) }}</span><span v-if="record.editedAt"> · Edited {{ commentDate(record.editedAt, appointment(record).timeZone) }}</span><a :href="href(record)" @click.prevent="open(record)">Session: {{ commentDate(appointment(record).startAt, appointment(record).timeZone) }} · {{ appointment(record).timeZone }}</a><button type="button" @click="open(record)">Open securely →</button></li></ol><button v-if="hasMore" type="button" :disabled="loading" @click="load(true)">Older secure comments</button></section></template>
<style scoped>.aw-secure-history{padding:20px;margin:20px 0;border:1px solid #dce5f0;border-radius:12px;background:#fff;color:#172d50}.aw-secure-history h3{margin:0}.aw-secure-history p,.aw-secure-history span{font-size:13px;color:#506783}.aw-secure-history ol{list-style:none;padding:0}.aw-secure-history li{padding:14px 0;border-top:1px solid #e0e8f2}.aw-secure-history a{display:block;color:#0047a7;margin:6px 0}.aw-secure-history button{border:1px solid #c5d5e9;border-radius:8px;background:#f6f9ff;padding:8px 12px;color:#164678;cursor:pointer}</style>
